{"engines/numeric/model.py": "import json
import math
from pathlib import Path


def _reject_non_finite(obj):
    if isinstance(obj, float):
        if math.isnan(obj) or math.isinf(obj):
            raise ValueError("non-finite number")
    elif isinstance(obj, list):
        for item in obj:
            _reject_non_finite(item)
    elif isinstance(obj, dict):
        for value in obj.values():
            _reject_non_finite(value)


def load_payload(path):
    path = Path(path)
    text = path.read_text(encoding="utf-8")
    try:
        data = json.loads(text)
    except json.JSONDecodeError as exc:
        raise ValueError("invalid JSON") from exc
    if not isinstance(data, (dict, list)):
        raise ValueError("top-level must be object or array")
    _reject_non_finite(data)
    return data
", "engines/numeric/transform.py": "import math


def _is_finite_number(value):
    if isinstance(value, bool):
        return False
    if isinstance(value, int):
        return True
    if isinstance(value, float):
        return math.isfinite(value)
    return False


def transform(payloads, contract):
    if len(payloads) != len(contract["inputs"]):
        raise ValueError("payload count mismatch")

    payload = payloads[0]
    if isinstance(payload, dict) and set(payload) == {"name", "result"}:
        payload = payload["result"]

    records = payload["records"]

    groups = {}
    for record in records:
        key = record["key"]
        value = record["value"]
        entry = groups.setdefault(key, {"count": 0, "sum": 0})
        if value is None:
            continue
        if not _is_finite_number(value):
            raise ValueError("value must be finite number or null")
        entry["count"] += 1
        entry["sum"] += value

    rows = []
    for key in sorted(groups):
        entry = groups[key]
        count = entry["count"]
        total = entry["sum"]
        mean = total / count if count else None
        rows.append(
            {
                "key": key,
                "values": {"count": count, "sum": total, "mean": mean},
            }
        )

    return {"name": contract["name"], "result": {"rows": rows}}
