import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def _attention(components):
    names = []
    for name, result in components.items():
        if not isinstance(result, dict):
            continue
        if result.get("blocked") is True:
            names.append(name)
            continue
        for field in ("complete", "checkout", "committed", "ok"):
            if result.get(field) is False:
                names.append(name)
                break
        else:
            for field in ("unavailable", "missing", "conflicts", "unreachable"):
                value = result.get(field)
                if isinstance(value, (list, dict, str, tuple)) and len(value) > 0:
                    names.append(name)
                    break
    return sorted(set(names))


def main():
    core_path = ROOT / "outputs" / "core_manifest.json"
    core = json.loads(core_path.read_text(encoding="utf-8"))
    components = core["components"]

    serialized = json.dumps(
        core,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")
    sha256 = hashlib.sha256(serialized).hexdigest()

    report = {
        "title": "聚合特征的行键保真与特征合并",
        "component_count": len(components),
